//! Embedded game data (block states, collision shapes, items, entity types)
//! generated by `tools/gen_game_data.py` from vanilla-extracted data.

use once_cell::sync::Lazy;
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Debug, Deserialize)]
pub struct BlockInfo {
    pub id: u32,
    pub name: String,
    pub hardness: f32,
    pub requires_tool: bool,
    pub color: u32,
    pub default_state: u32,
    pub item: String,
    pub friction: f32,
}

#[derive(Debug, Deserialize)]
pub struct ItemInfo {
    pub id: u32,
    pub name: String,
    pub stack: u32,
    pub max_damage: u32,
    pub food: u32,
    pub tool_speed: f32,
    pub block: String,
}

#[derive(Debug, Deserialize)]
pub struct EntityInfo {
    pub id: u32,
    pub name: String,
    pub width: f32,
    pub height: f32,
    pub kind: String,
    pub max_health: f32,
}

/// (block id, property string, collision shape index, flags)
#[derive(Debug, Deserialize)]
pub struct StateRow(pub u32, pub String, pub u32, pub u8);

#[derive(Debug, Deserialize)]
struct Raw {
    version: String,
    protocol: i32,
    blocks: Vec<BlockInfo>,
    states: Vec<StateRow>,
    shapes: Vec<Vec<[f64; 6]>>,
    items: Vec<ItemInfo>,
    entities: Vec<EntityInfo>,
    tags: HashMap<String, Vec<String>>,
}

pub const FLAG_SOLID: u8 = 1;
pub const FLAG_FLUID: u8 = 2;
pub const FLAG_OCCLUDES: u8 = 4;

pub struct GameData {
    pub version: String,
    pub protocol: i32,
    pub blocks: Vec<BlockInfo>,
    pub states: Vec<StateRow>,
    pub shapes: Vec<Vec<[f64; 6]>>,
    pub items: Vec<ItemInfo>,
    pub entities: Vec<EntityInfo>,
    block_by_name: HashMap<String, u32>,
    item_by_name: HashMap<String, u32>,
    tags: HashMap<String, std::collections::HashSet<String>>,
}

static DATA_26_3: &str = include_str!("../data/game_data_26_3.json");

pub static GAME: Lazy<GameData> = Lazy::new(|| {
    let raw: Raw = serde_json::from_str(DATA_26_3).expect("embedded game data is valid JSON");
    let block_by_name = raw.blocks.iter().map(|b| (b.name.clone(), b.id)).collect();
    let item_by_name = raw.items.iter().map(|i| (i.name.clone(), i.id)).collect();
    let tags = raw.tags.into_iter().map(|(k, v)| (k, v.into_iter().collect())).collect();
    GameData {
        version: raw.version,
        protocol: raw.protocol,
        blocks: raw.blocks,
        states: raw.states,
        shapes: raw.shapes,
        items: raw.items,
        entities: raw.entities,
        block_by_name,
        item_by_name,
        tags,
    }
});

impl GameData {
    pub fn state(&self, state: u32) -> Option<&StateRow> {
        self.states.get(state as usize)
    }

    pub fn block_of_state(&self, state: u32) -> Option<&BlockInfo> {
        self.state(state).and_then(|s| self.blocks.get(s.0 as usize))
    }

    pub fn block_name(&self, state: u32) -> &str {
        self.block_of_state(state).map(|b| b.name.as_str()).unwrap_or("unknown")
    }

    pub fn block_by_name(&self, name: &str) -> Option<&BlockInfo> {
        self.block_by_name.get(name.trim_start_matches("minecraft:")).and_then(|i| self.blocks.get(*i as usize))
    }

    pub fn collision(&self, state: u32) -> &[[f64; 6]] {
        match self.state(state) {
            Some(s) => &self.shapes[s.2 as usize],
            None => &[],
        }
    }

    pub fn is_air(&self, state: u32) -> bool {
        matches!(self.block_name(state), "air" | "cave_air" | "void_air")
    }

    pub fn is_fluid(&self, state: u32) -> bool {
        let n = self.block_name(state);
        n == "water" || n == "lava" || self.state(state).map(|s| s.3 & FLAG_FLUID != 0).unwrap_or(false)
    }

    pub fn is_solid(&self, state: u32) -> bool {
        !self.collision(state).is_empty()
    }

    /// Value of a block-state property, e.g. `axis` → `y`.
    pub fn prop<'a>(&'a self, state: u32, key: &str) -> Option<&'a str> {
        let s = self.state(state)?;
        s.1.split(',').find_map(|kv| {
            let (k, v) = kv.split_once('=')?;
            (k == key).then_some(v)
        })
    }

    pub fn item(&self, id: u32) -> Option<&ItemInfo> {
        self.items.get(id as usize)
    }

    pub fn item_name(&self, id: u32) -> &str {
        self.item(id).map(|i| i.name.as_str()).unwrap_or("unknown")
    }

    pub fn item_by_name(&self, name: &str) -> Option<&ItemInfo> {
        self.item_by_name.get(name.trim_start_matches("minecraft:")).and_then(|i| self.items.get(*i as usize))
    }

    pub fn entity(&self, id: u32) -> Option<&EntityInfo> {
        self.entities.get(id as usize)
    }

    pub fn in_tag(&self, tag: &str, block: &str) -> bool {
        self.tags.get(tag).map(|t| t.contains(block)).unwrap_or(false)
    }
}

pub fn is_hostile(entity: &str) -> bool {
    matches!(
        entity,
        "zombie" | "husk" | "drowned" | "skeleton" | "stray" | "bogged" | "creeper" | "spider" | "cave_spider"
            | "enderman" | "witch" | "slime" | "magma_cube" | "phantom" | "pillager" | "vindicator" | "evoker"
            | "ravager" | "blaze" | "ghast" | "wither_skeleton" | "piglin_brute" | "hoglin" | "zoglin"
            | "silverfish" | "endermite" | "guardian" | "elder_guardian" | "shulker" | "vex" | "warden"
            | "zombie_villager" | "breeze" | "creaking" | "parched"
    )
}

pub fn is_food_animal(entity: &str) -> bool {
    matches!(entity, "cow" | "pig" | "sheep" | "chicken" | "rabbit" | "mooshroom")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_loads() {
        assert_eq!(GAME.protocol, 777);
        assert_eq!(GAME.block_name(0), "air");
        assert_eq!(GAME.block_name(1), "stone");
        assert_eq!(GAME.block_by_name("grass_block").unwrap().default_state, 9);
        assert!(GAME.is_solid(1));
        assert!(!GAME.is_solid(0));
        assert_eq!(GAME.item_by_name("oak_log").unwrap().id, 163);
        assert!(GAME.in_tag("mineable/pickaxe", "stone"));
        assert!(GAME.in_tag("logs", "oak_log"));
        let slab = GAME.block_by_name("oak_slab").unwrap().default_state;
        assert_eq!(GAME.prop(slab, "type"), Some("bottom"));
        assert_eq!(GAME.collision(slab), &[[0.0, 0.0, 0.0, 1.0, 0.5, 1.0]]);
    }
}
